<script setup lang="ts">
import {onMounted,onUnmounted,reactive,ref} from 'vue';import {cents,type RequestFn} from './media';import {date,money,states} from './lib';import {localDate} from './schema';
const props=defineProps<{request:RequestFn}>();const rows=ref<Record<string,any>[]>([]),editing=ref<Record<string,any>|null>(null),busy=ref(false),error=ref(''),notice=ref('');const form=reactive({verified_reference:'',amount:'',received_at:'',note:'',confirmed:false});
async function load(){rows.value=await props.request('admin/manual-payments')}
async function open(row:Record<string,any>){error.value='';editing.value=await props.request('admin/manual-payments/'+row.id);Object.assign(form,{verified_reference:'',amount:(row.payable/100).toFixed(2),received_at:localDate(new Date()),note:'',confirmed:false})}
async function decide(decision:string){busy.value=true;error.value='';notice.value='';try{const body={decision,version:editing.value?.version,verified_reference:form.verified_reference,received_amount:decision==='approve'?cents(form.amount):0,received_at:decision==='approve'?new Date(form.received_at).toISOString():new Date(0).toISOString(),note:form.note,confirmed:form.confirmed};const d=await props.request('admin/manual-payments/'+editing.value?.id,'PUT',body);notice.value=d.message;editing.value=null;await load()}catch(e){error.value=String(e instanceof Error?e.message:e)}finally{busy.value=false}}
let timer:ReturnType<typeof setInterval>;onMounted(()=>{void load().catch(e=>error.value=String(e));timer=setInterval(()=>{if(document.visibilityState==='visible'&&!editing.value&&!busy.value)void load().catch(()=>{})},30000)});onUnmounted(()=>clearInterval(timer));
</script>
<template><div class="alert">请到支付宝或微信核对真实到账记录，截图或用户自填流水不能作为自动到账依据。确认后按原订单金额开通，重复审核不会重复发放。</div><div v-if="error" class="alert error">{{error}}</div><div v-if="notice" class="alert">{{notice}}</div><section class="panel table-wrap"><table><thead><tr><th>用户 / 订单</th><th>收款方式</th><th>应付</th><th>凭证状态</th><th>提交时间</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td><strong>{{r.name}}</strong><small>{{r.email}}</small><small class="mono">{{r.order_id}}</small></td><td>{{r.method_name}}</td><td>{{money(r.payable)}}</td><td><span class="badge" :class="r.state">{{states[r.state]||r.state}}</span></td><td>{{date(r.submitted_at)}}</td><td><button @click="open(r)">查看 / 核款</button></td></tr></tbody></table><div v-if="!rows.length" class="empty">暂无个人收款订单</div></section><div v-if="editing" class="modal-backdrop" @click.self="editing=null"><section class="modal" role="dialog" aria-modal="true" aria-label="核实付款"><div class="section-head"><h2>核实实际到账</h2><button @click="editing=null" aria-label="关闭">×</button></div><div v-if="error" class="alert error">{{error}}</div><p>{{editing.name}} · {{editing.email}}</p><p>应付 {{money(editing.payable)}} · {{editing.method_name}}</p><p class="muted">用户填报流水：{{editing.reference||'未填写'}}</p><p class="pre muted">{{editing.payer_note}}</p><img v-if="editing.proof_available" :src="'/portal/v1/orders/'+editing.order_id+'/receipt?v='+editing.version" class="receipt-preview" alt="用户提交的付款凭证"><p v-if="editing.review_note" class="alert">{{editing.review_note}}</p><template v-if="editing.state==='submitted'&&editing.order_state==='pending'"><div class="fields"><label>已核实的真实交易流水<input v-model="form.verified_reference" minlength="6" maxlength="100"></label><label>实际收到金额（元）<input v-model="form.amount" inputmode="decimal"></label><label>真实到账时间<input type="datetime-local" v-model="form.received_at"></label><label>审核说明<textarea v-model="form.note" rows="2" maxlength="1000"/></label></div><label class="multi"><input type="checkbox" v-model="form.confirmed">我已在收款账户核实到账、金额和交易流水</label><div class="actions"><button class="primary" @click="decide('approve')" :disabled="busy||!form.confirmed||!form.verified_reference">确认到账并开通</button><button @click="decide('reject')" :disabled="busy||!form.note.trim()">驳回并说明原因</button></div></template><div v-else class="muted">当前状态 {{states[editing.state]||editing.state}}<p v-if="editing.verified_reference">核实流水：{{editing.verified_reference}} · 实收 {{money(editing.received_amount)}} · {{date(editing.received_at)}}</p></div></section></div></template>
